class Solution {
    public String mergeAlternately(String word1,String word2){
        StringBuilder answer=new StringBuilder();
        for(int i=0;i<Math.max(word1.length(),word2.length());i++){
            if(i<word1.length())answer.append(word1.charAt(i));
            if(i<word2.length())answer.append(word2.charAt(i));
        }
        return answer.toString();
    }
}

code.kotlin:
class Solution {
    fun mergeAlternately(word1:String,word2:String):String{
        val answer=StringBuilder();
        for(i in 0 until maxOf(word1.length,word2.length)){
            if(i<word1.length)answer.append(word1[i]);
            if(i<word2.length)answer.append(word2[i])
        };
        return answer.toString()
    }
}

